  assert.ok(Math.abs(target.holdX - scent.x) > 20 || Math.abs(target.holdLift - scent.lift) > 20, "not Rue");
  assert.ok(Math.abs(target.holdX - thump.x) > 20 || Math.abs(target.holdLift - thump.lift) > 20, "not Thimble");
