  assert.ok(Math.abs(target.holdX - holdClip.x) > 20 || Math.abs(target.holdLift - holdClip.lift) > 16, "not Fuse");
  assert.ok(Math.abs(target.holdLift - sill.lift) > 40, "not a generic sill");
