  assert.ok(P.DUR.lick !== Overlay.DUR.count);
  assert.ok(P.DUR.lick !== Overlay.DUR.gold);
  assert.ok(P.DUR.lick !== Overlay.DUR.flatten);
  assert.ok(P.DUR.lick !== Overlay.DUR.lean);
  assert.ok(P.DUR.lick !== Overlay.DUR.chime);
  assert.ok(P.DUR.lick !== Overlay.DUR.kindle);
