  assert.notEqual(target.kind, "flatten");
  assert.notEqual(target.kind, "unfurl");
  assert.notEqual(target.kind, "path");
  assert.notEqual(target.kind, "bun");
  assert.notEqual(target.kind, "sill");
  assert.ok(P.DUR.cover < P.DUR.coverHold, "the cover is the tell; the hold is the coins after");
  assert.ok(P.DUR.coverOn !== Overlay.DUR.trailOn);
  assert.ok(P.DUR.coverOn !== Overlay.DUR.puffOn);
  assert.ok(P.DUR.coverOn !== Overlay.DUR.plopOn);
  assert.ok(P.DUR.coverOn !== Overlay.DUR.baskOn);
