    if (play.phase === "claw") {
      clawLiftMax = Math.max(clawLiftMax, play.lift - play.target.holdLift);
      clawLiftMin = Math.min(clawLiftMin, play.lift - play.target.holdLift);
      assert.equal(play.anim, "play");
    }
