  assert.equal(P.playFor("axolotl"), "wall");
  assert.equal(P.playFor("sea_star"), "reef");
  assert.equal(P.playFor("phoenix"), "kindle");
  assert.equal(P.playFor("cyber_dragon"), "ridge");
