  assert.ok(P.DUR.raspOn !== Overlay.DUR.ringOn);
  assert.ok(P.DUR.raspOn !== Overlay.DUR.coverOn);
  assert.ok(P.DUR.raspOn !== Overlay.DUR.trailOn);
