  assert.ok(P.DUR.rasp !== Overlay.DUR.cover);
  assert.ok(P.DUR.rasp !== Overlay.DUR.trail);
  assert.ok(P.DUR.rasp !== Overlay.DUR.puff);
  assert.ok(P.DUR.rasp !== Overlay.DUR.plop);
