  assert.equal(P.playFor("stickleback"), "glue");
  assert.equal(P.playFor("octopus"), "lid");
  assert.equal(P.playFor("hermit_crab"), "knob");
  assert.equal(P.playFor("cyber_dragon"), "ridge");
  assert.equal(P.playFor("phoenix"), "kindle");
  assert.equal(P.playFor("gecko"), "sill");
  assert.equal(P.playFor("pileated"), "drum");
  assert.notEqual(target.kind, "vee");
  assert.notEqual(target.kind, "goose");
  assert.notEqual(target.kind, "tip");
  assert.notEqual(target.kind, "pull");
  assert.notEqual(target.kind, "cache");
  assert.notEqual(target.kind, "soar");
  assert.notEqual(target.kind, "loop");
  assert.notEqual(target.kind, "sill");
  assert.ok(P.DUR.honk > P.DUR.honkHold, "the honk is the tell; the apron sit is the hold after");
  assert.ok(P.DUR.honkOn !== Overlay.DUR.tipOn);
  assert.ok(P.DUR.honkOn !== Overlay.DUR.pullOn);
  assert.ok(P.DUR.honkOn !== Overlay.DUR.cacheOn);
  assert.ok(P.DUR.honkOn !== Overlay.DUR.soarOn);
  assert.ok(P.DUR.honkOn !== Overlay.DUR.loopOn);
  assert.ok(P.DUR.honkOn !== Overlay.DUR.sillHop);
  assert.ok(P.DUR.honk !== Overlay.DUR.tip);
  assert.ok(P.DUR.honk !== Overlay.DUR.pull);
  assert.ok(P.DUR.honk !== Overlay.DUR.cache);
  assert.ok(P.DUR.honk !== Overlay.DUR.loop);
