  const river = P.loopPoint(WIN, 176, WORK);
  const cup = P.cachePoint(WIN, 176, WORK);
  const pad = P.openPoint(WIN, 176, WORK);
  const bowl = P.fieldPoint(WIN, 176, WORK);
