  assert.notEqual(target.kind, "pileated");
  assert.notEqual(target.kind, "honk");
  assert.notEqual(target.kind, "soar");
  assert.notEqual(target.kind, "bore");
  assert.notEqual(target.kind, "sip");
  assert.notEqual(target.kind, "hover");
