  assert.ok(P.DUR.drumOn !== Overlay.DUR.soarOn);
  assert.ok(P.DUR.drumOn !== Overlay.DUR.boreOn);
  assert.ok(P.DUR.drumOn !== Overlay.DUR.sillHop);
  assert.ok(P.DUR.drum !== Overlay.DUR.honk);
  assert.ok(P.DUR.drum !== Overlay.DUR.bore);
  assert.ok(P.DUR.drumHold !== Overlay.DUR.honkHold);
  assert.ok(P.DUR.drumOff !== Overlay.DUR.honkOff);
  assert.equal(P.DUR.drumOn, Overlay.DUR.drumOn);
  assert.equal(P.DUR.drum, Overlay.DUR.drum);
  assert.equal(P.DUR.drumHold, Overlay.DUR.drumHold);
  assert.equal(P.DUR.drumOff, Overlay.DUR.drumOff);
  const snag = P.drumPoint(WIN, 176, WORK);
  const deskSnag = Overlay.drumPoint(WIN, 176, WORK);
  assert.equal(snag.x, deskSnag.x);
