  const soffit = P.foldPoint(WIN, 176, WORK);
  const rafter = P.croakPoint(WIN, 176, WORK);
  const dark = P.hangPoint(WIN, 176, WORK);
  const duff = P.stampPoint(WIN, 176, WORK);
